// Reglas fijas: NO usan IA, son exactas
const pdf = $input.first().json;
const chat = $('Chat del autor').first().json;

const paginas = Number(pdf.numpages) || 0;
const texto = (pdf.text || '').replace(/\s+/g, ' ').trim();

// Título: metadatos del PDF solo si son reales; si no, las primeras líneas del texto
const basura = ['', 'untitled', '(anonymous)', 'anonymous', '(unspecified)'];
const tituloMeta = String((pdf.info && pdf.info.Title) || '').trim();
let titulo = basura.includes(tituloMeta.toLowerCase()) ? '' : tituloMeta;
if (!titulo) {
  const lineas = (pdf.text || '').split('\n').map(l => l.trim()).filter(Boolean);
  const partes = [];
  for (const l of lineas) {
    if (/^(autor|resumen|abstract|palabras clave)/i.test(l) || partes.length >= 3) break;
    partes.push(l);
  }
  titulo = partes.join(' ').replace(/\s+/g, ' ').trim() || 'Sin título';
}

return [{ json: {
  sessionId: chat.sessionId,
  mensajeAutor: chat.chatInput || '',
  nombreArchivo: (chat.files && chat.files[0] && chat.files[0].fileName) || 'archivo.pdf',
  titulo,
  paginas,
  cumplePaginas: paginas > 0 && paginas <= 10,
  tieneTexto: texto.length > 500,
  textoPDF: texto.slice(0, 15000)
}}];

