// Convierte la respuesta del orquestador (texto JSON) en campos, con guardrails
const raw = $input.first().json.output;
let d = null;
if (raw && typeof raw === 'object') d = raw;
else {
  const m = String(raw || '').match(/\{[\s\S]*\}/);
  if (m) { try { d = JSON.parse(m[0]); } catch (e) { d = null; } }
}
// Si la IA no respondió en JSON, se trata como conversación normal
if (!d || !d.accion) d = { accion: 'conversar', respuesta_autor: String(raw || '') };
if (!['conversar', 'rechazar', 'enviar_a_revision'].includes(d.accion)) d.accion = 'conversar';
const campos = ['respuesta_autor','nombre_autor','correo_autor','titulo','resumen_formato','motivo','posible_duplicado',
  'revisor_1_nombre','revisor_1_correo','revisor_1_area','revisor_2_nombre','revisor_2_correo','revisor_2_area'];
for (const c of campos) d[c] = (d[c] === undefined || d[c] === null) ? '' : String(d[c]);
d.respuesta_autor = d.respuesta_autor.replace(/\\n/g, '\n');
// Guardrail: sin correo válido no se envía nada al editor
if (d.accion !== 'conversar' && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(d.correo_autor)) {
  d.accion = 'conversar';
  d.respuesta_autor += '\n\nPara continuar necesito tu correo electrónico. Escríbelo y vuelve a adjuntar el PDF.';
}
// Guardrail: para enviar a revisión se necesitan 2 revisores con correo
if (d.accion === 'enviar_a_revision' && (!d.revisor_1_correo || !d.revisor_2_correo)) {
  d.motivo = (d.motivo + ' (La IA no pudo asignar 2 revisores; requiere asignación manual.)').trim();
}
return [{ json: d }];

